// Declarações reais do TypeScript 5.9.3:
// lib.es5.d.ts:  parse(text: string, reviver?: ...): any;
// lib.dom.d.ts:  json(): Promise<any>;

// Uma "API" local: devolve o texto que um servidor enviaria.
async function servidor(): Promise<string> {
  return '{"id": 7, "nome": "Rita", "ativo": true}';
}

const texto = await servidor();
const viaParse = JSON.parse(texto); // viaParse: any

const resposta = new Response(texto, { status: 200 });
const viaJson = await resposta.json(); // viaJson: any

console.log(resposta.status, viaParse.nome, viaJson.id); // 200 Rita 7

async function servidor(): Promise<string> {
  // O servidor mudou o formato: "nome" passou a "nomeCompleto".
  return '{"id": 7, "nomeCompleto": "Rita Sousa"}';
}

const utilizador = JSON.parse(await servidor()); // any

// Tudo compila: com any o compilador não verifica nada.
const id: string = utilizador.id; // mentira: em runtime é um number
console.log(typeof id);           // number
console.log(utilizador.nome);     // undefined

function iniciais(nome: string): string {
  return nome.split(" ").map((p) => p[0]).join("");
}

try {
  // O erro só rebenta aqui, longe do JSON.parse que o causou.
  console.log(iniciais(utilizador.nome));
} catch (erro) {
  console.log("Falhou:", (erro as Error).message);
  // Falhou: Cannot read properties of undefined (reading 'split')
}

type Utilizador = { id: number; nome: string };

async function servidor(): Promise<string> {
  return '{"codigo": 404, "erro": "não encontrado"}';
}

// Genérico de conveniência: parece seguro, mas é só um cast escondido.
async function obterJson<T>(): Promise<T> {
  const texto = await servidor();
  return JSON.parse(texto); // any passa sem queixa para T
}

const u = await obterJson<Utilizador>(); // u: Utilizador (segundo o tipo)
console.log(u.nome);                     // undefined

// O mesmo com "as": o compilador aceita a palavra de quem escreve.
const v = JSON.parse(await servidor()) as Utilizador;
console.log(typeof v.id);                // undefined

// @ts-expect-error TS2558: Expected 0 type arguments, but got 1. JSON.parse não é genérico.
const tentativa = JSON.parse<{ nome: string }>('{"nome": "Ana"}');

// A anotação transforma o any em unknown logo na fronteira.
const dados: unknown = JSON.parse('{"nome": "Ana", "idade": 30}');

// @ts-expect-error TS18046: 'dados' is of type 'unknown'.
console.log(dados.nome);

// @ts-expect-error TS18046: 'dados' is of type 'unknown'.
const idade: number = dados.idade + 1;

// Atribuir unknown a um tipo concreto também é recusado.
// @ts-expect-error TS2322: Type 'unknown' is not assignable to type 'string'.
const nome: string = dados;

// Passar unknown para onde se espera unknown é sempre permitido.
const copia: unknown = dados;

const dados: unknown = JSON.parse('{"nome": "Ana", "tags": ["a", "b"]}');

if (typeof dados === "object" && dados !== null) {
  // dados: object
  if ("nome" in dados) {
    // dados: object & Record<"nome", unknown>
    const campo = dados.nome; // campo: unknown
    if (typeof campo === "string") {
      console.log(campo.toUpperCase()); // ANA
    }
  }
  if ("tags" in dados && Array.isArray(dados.tags)) {
    // Cuidado: Array.isArray dá any[], e o any volta a entrar.
    const tags = dados.tags; // tags: any[]
    try {
      console.log(tags[0].nao.existe); // compila, mas rebenta
    } catch (erro) {
      console.log("Falhou:", (erro as Error).message);
      // Falhou: Cannot read properties of undefined (reading 'existe')
    }
    // Correção: guardar logo como unknown[].
    const seguras: unknown[] = dados.tags;
    console.log(seguras.filter((t) => typeof t === "string").length); // 2
  }
}

type Utilizador = { id: number; nome: string; ativo: boolean };

// A fronteira: recebe unknown, devolve um tipo do domínio ou null.
function parseUtilizador(valor: unknown): Utilizador | null {
  if (typeof valor !== "object" || valor === null) return null;
  if (!("id" in valor) || typeof valor.id !== "number") return null;
  if (!("nome" in valor) || typeof valor.nome !== "string") return null;
  if (!("ativo" in valor) || typeof valor.ativo !== "boolean") return null;
  // valor continua a ser object & Record<...>, por isso constrói-se um objeto novo.
  return { id: valor.id, nome: valor.nome, ativo: valor.ativo };
}

async function pedir(corpo: string): Promise<Response> {
  return new Response(corpo, { status: 200 }); // simula a rede
}

async function obterUtilizador(corpo: string): Promise<Utilizador | null> {
  const resposta = await pedir(corpo);
  const dados: unknown = await resposta.json();
  return parseUtilizador(dados);
}

// O interior só vê Utilizador: nada de verificações aqui.
function saudacao(u: Utilizador): string {
  return `${u.ativo ? "Olá" : "Adeus"}, ${u.nome} (#${u.id})`;
}

const bom = await obterUtilizador('{"id": 1, "nome": "Rui", "ativo": true}');
const mau = await obterUtilizador('{"id": "1", "nome": "Rui"}');

console.log(bom ? saudacao(bom) : "dados inválidos"); // Olá, Rui (#1)
console.log(mau ? saudacao(mau) : "dados inválidos"); // dados inválidos

type Config = { tema: "claro" | "escuro"; tamanho: number };

// satisfies verifica um valor ESCRITO no código; não serve para dados de fora.
const predefinida = { tema: "claro", tamanho: 14 } satisfies Config;

function parseConfig(valor: unknown): Config {
  if (typeof valor === "object" && valor !== null &&
      "tema" in valor && (valor.tema === "claro" || valor.tema === "escuro") &&
      "tamanho" in valor && typeof valor.tamanho === "number") {
    return { tema: valor.tema, tamanho: valor.tamanho };
  }
  return predefinida; // entrada estragada: volta ao valor seguro
}

// Simula o que viria de localStorage.getItem("config").
const guardado: string = '{"tema": "roxo", "tamanho": 16}';
const config = parseConfig(JSON.parse(guardado));
console.log(config.tema, config.tamanho); // claro 14

