function lerContador(texto: string): number {
  const dados: unknown = JSON.parse(texto);
  if (typeof dados === "number" && Number.isFinite(dados)) {
    return dados;
  }
  return 0;
}

console.log(lerContador("42"));      // 42
console.log(lerContador('"42"'));    // 0
console.log(lerContador("null"));    // 0

type Produto = { nome: string; preco: number };

function parseProduto(valor: unknown): Produto | null {
  if (typeof valor !== "object" || valor === null) return null;
  if (!("nome" in valor) || typeof valor.nome !== "string") return null;
  if (!("preco" in valor) || typeof valor.preco !== "number") return null;
  return { nome: valor.nome, preco: valor.preco };
}

console.log(parseProduto(JSON.parse('{"nome": "Caneta", "preco": 1.5}')));
// { nome: 'Caneta', preco: 1.5 }
console.log(parseProduto(JSON.parse('{"nome": "Caneta", "preco": "1.5"}'))); // null
console.log(parseProduto(JSON.parse("[]")));                                 // null

type Produto = { nome: string; preco: number };

function parseProduto(valor: unknown): Produto | null {
  if (typeof valor !== "object" || valor === null) return null;
  if (!("nome" in valor) || typeof valor.nome !== "string") return null;
  if (!("preco" in valor) || typeof valor.preco !== "number") return null;
  return { nome: valor.nome, preco: valor.preco };
}

function parseCatalogo(valor: unknown): Produto[] {
  if (!Array.isArray(valor)) return [];
  const itens: unknown[] = valor; // fecha a porta ao any[]
  const produtos: Produto[] = [];
  for (const item of itens) {
    const p = parseProduto(item);
    if (p !== null) produtos.push(p);
  }
  return produtos;
}

const texto = '[{"nome": "Lápis", "preco": 0.8}, {"nome": 3}, null, {"nome": "Borracha", "preco": 0.5}]';
const catalogo = parseCatalogo(JSON.parse(texto));
console.log(catalogo.length);                                  // 2
console.log(catalogo.reduce((soma, p) => soma + p.preco, 0));  // 1.3

type Resposta =
  | { estado: "ok"; total: number }
  | { estado: "erro"; mensagem: string };

function parseResposta(valor: unknown): Resposta {
  if (typeof valor === "object" && valor !== null && "estado" in valor) {
    if (valor.estado === "ok" && "total" in valor && typeof valor.total === "number") {
      return { estado: "ok", total: valor.total };
    }
    if (valor.estado === "erro" && "mensagem" in valor && typeof valor.mensagem === "string") {
      return { estado: "erro", mensagem: valor.mensagem };
    }
  }
  throw new Error("Resposta com formato inesperado");
}

async function consultar(corpo: string): Promise<Resposta> {
  const resposta = new Response(corpo); // simula a rede
  const dados: unknown = await resposta.json();
  return parseResposta(dados);
}

function descrever(r: Resposta): string {
  return r.estado === "ok" ? `Total: ${r.total}` : `Erro: ${r.mensagem}`;
}

for (const corpo of ['{"estado": "ok", "total": 12}', '{"estado": "erro", "mensagem": "sem stock"}', '{"estado": "ok"}']) {
  try {
    console.log(descrever(await consultar(corpo)));
  } catch (erro) {
    console.log("Rejeitado:", (erro as Error).message);
  }
}
// Total: 12
// Erro: sem stock
// Rejeitado: Resposta com formato inesperado
